import{_ as a,H as p,f as l,i}from"./chunks/framework.BH2BK_3i.js";const E=JSON.parse('{"title":"06-认识市场：技术岗不变的价值在哪里？","description":"","frontmatter":{},"headers":[{"level":2,"title":"变化的市场中技术的价值","slug":"变化的市场中技术的价值","link":"#变化的市场中技术的价值","children":[{"level":3,"title":"价值 1：数字化","slug":"价值-1-数字化","link":"#价值-1-数字化","children":[]},{"level":3,"title":"价值 2：规模化","slug":"价值-2-规模化","link":"#价值-2-规模化","children":[]},{"level":3,"title":"价值 3：智能化","slug":"价值-3-智能化","link":"#价值-3-智能化","children":[]},{"level":3,"title":"价值 4：底层能力建设","slug":"价值-4-底层能力建设","link":"#价值-4-底层能力建设","children":[]}]},{"level":2,"title":"从当下市场需求看未来的方向","slug":"从当下市场需求看未来的方向","link":"#从当下市场需求看未来的方向","children":[{"level":3,"title":"数字化：传统行业的数字化转型","slug":"数字化-传统行业的数字化转型","link":"#数字化-传统行业的数字化转型","children":[]},{"level":3,"title":"智能化：AI 未来可期","slug":"智能化-ai-未来可期","link":"#智能化-ai-未来可期","children":[]},{"level":3,"title":"底层能力建设：赋能企业，攻坚“卡脖子”技术","slug":"底层能力建设-赋能企业-攻坚-卡脖子-技术","link":"#底层能力建设-赋能企业-攻坚-卡脖子-技术","children":[]}]},{"level":2,"title":"永恒的变化","slug":"永恒的变化","link":"#永恒的变化","children":[]},{"level":2,"title":"小结时刻","slug":"小结时刻","link":"#小结时刻","children":[]},{"level":2,"title":"聊聊发展","slug":"聊聊发展","link":"#聊聊发展","children":[]}],"relativePath":"程序员职业规划手册/06-认识市场：技术岗不变的价值在哪里？.md","filePath":"程序员职业规划手册/06-认识市场：技术岗不变的价值在哪里？.md","lastUpdated":1795563381000}'),t={name:"程序员职业规划手册/06-认识市场：技术岗不变的价值在哪里？.md"};function r(n,e,h,o,s,d){return p(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="_06-认识市场-技术岗不变的价值在哪里" tabindex="-1">06-认识市场：技术岗不变的价值在哪里？ <a class="header-anchor" href="#_06-认识市场-技术岗不变的价值在哪里" aria-label="Permalink to &quot;06-认识市场：技术岗不变的价值在哪里？&quot;">​</a></h1><p>你好，我是雪梅。</p><p>我们在第一章聊了 5 个职场发展的关键问题。但要说这 5 节课就能解决所有职场问题，那肯定是不现实的。想要在众多岔路口中选出最适合自己的路，打出 1+1&gt;2 的效果，我们还需要“向外看”和“向内看”这两种视角，重新认识环境、认识自己。</p><p>这两年互联网形式变化剧烈，很多小伙伴对于未来的发展前景有很多的焦虑。比如有不少小伙伴会问，AI 快速发展，未来技术岗还有哪些机会？</p><p>其实，我特别能理解小伙伴的困惑与迷茫，在这个瞬息万变的时代，任何对于未来的预测行为都是徒劳的。但我们可以换个角度思考这个问题，产生这样的困惑，最主要的原因，就是没有看到在变化的市场需求背后，技术提供了哪些不变的价值。反过来讲，只要未来的市场依然有这部分需求，技术岗就依然有发展前景。</p><p>那这一节，我们就来聊聊技术岗的价值和未来的可能。</p><h2 id="变化的市场中技术的价值" tabindex="-1">变化的市场中技术的价值 <a class="header-anchor" href="#变化的市场中技术的价值" aria-label="Permalink to &quot;变化的市场中技术的价值&quot;">​</a></h2><p>中国互联网发展了将近三十年，无论是 Windows 时期，PC 互联网时期，还是移动互联网时期，虽然市场需求一直在变化，但技术的本质没有变。</p><p>在我看来，技术的本质是一种工具。当然，作为科技力量，技术比一般的工具能力更强。比如我们之前出门靠纸质地图、靠问路，生活半径有限。而如今，利用地理信息位置采集、卫星导航、路径规划等技术，我们有了智能导航系统，路痴也不用担心迷路问题了。</p><p>那在过去变化的市场需求中，技术发挥的价值有哪些？跟技术人的岗位又有什么关系呢？</p><p>我总结了 4 个方面的价值，一起来看看。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A8%8B%E5%BA%8F%E5%91%98%E8%81%8C%E4%B8%9A%E8%A7%84%E5%88%92%E6%89%8B%E5%86%8C/images/06-%25E8%25AE%25A4%25E8%25AF%2586%25E5%25B8%2582%25E5%259C%25BA/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A8%8B%E5%BA%8F%E5%91%98%E8%81%8C%E4%B8%9A%E8%A7%84%E5%88%92%E6%89%8B%E5%86%8C/images/06-%25E8%25AE%25A4%25E8%25AF%2586%25E5%25B8%2582%25E5%259C%25BA/1.png" alt=""></a></p><h3 id="价值-1-数字化" tabindex="-1">价值 1：数字化 <a class="header-anchor" href="#价值-1-数字化" aria-label="Permalink to &quot;价值 1：数字化&quot;">​</a></h3><p>数字化，就是把线下的世界搬到线上。</p><p>从市场层面看，淘宝最开始就是把很多店铺的商品线上化。搬到线上有什么好处呢？一方面可以利用互联网打破地域的限制。比如有了淘宝，新疆一个种和田玉大枣的农民，就可以把自己的大枣卖到全国各地。另一方面可以解放人力，提高效率。举个简单的例子，一个店铺有 5 个服务员，这 5 个人怎么排班呢？以前可能靠门店经理，拿个表格每周花时间排。现在明确一些限制条件，就能实现自动排班，减少门店经理的工作任务。</p><p>那这对技术人有啥影响呢？因为有很多需求需要实现，所以在过去很长的一段时间，前端、客户端开发以及后端业务研发的需求量都很大。尤其是移动互联网浪潮来临时，很多小伙伴虽然不是计算机专业，但是在学校做几个项目，加上自学，很快就能拿到一个不错的 Offer。</p><p>我认识的小 A 之前在西安一家小公司做开发，后来自学前端，密密麻麻地记了 16 万字的学习笔记。再之后，他来北漂了，很快拿到了百度的 Offer。后端的业务研发也有很多类似的案例。小 B 之前在一家小公司做开发，薪水很低，后来在一个学习社群里看到有大厂在发招聘信息，他认真准备了一下，也顺利拿到了大厂的 Offer。放到现在大家可能都不敢想，其实背后都是市场需求的变化。</p><h3 id="价值-2-规模化" tabindex="-1">价值 2：规模化 <a class="header-anchor" href="#价值-2-规模化" aria-label="Permalink to &quot;价值 2：规模化&quot;">​</a></h3><p>代码天然具备极强的可复制能力，在结构化存储之后，还可以进行复杂计算，这让系统具备了极强的规模效应。</p><p>什么意思呢？一个网站只有一个人访问的时候，背后的成本极高，但如果是一万人甚至更多的时候，边际成本几乎可以忽略。</p><p>规模化的背后，对于技术有很高的要求，这就跟咱们有关了。流量在迅猛地增长，如何设计高并发架构，如何做系统的性能优化，如何保障大流量之下的系统稳定运转……这都是一系列的技术课题。不仅非常考验业务研发的架构设计能力，测试的质量保障能力，也非常考验运维的精细化稳定性预案等等。阿里每年双十一之前，都要进行好多轮全链路压测，是一项非常浩大的工程。</p><p>在很长一段时间内，加入交易中心这种高并发的中台系统，是很多技术人无比向往的事。但这几年明显有降温。因为市场增速缓慢，新起来的大平台越来越少，而原有大平台积累的很多技术已经成熟了。这时候如果我们再想挤进某个成熟的交易平台去提升自己的技术能力，干的很有可能就是“拧螺丝”的工作了。</p><h3 id="价值-3-智能化" tabindex="-1">价值 3：智能化 <a class="header-anchor" href="#价值-3-智能化" aria-label="Permalink to &quot;价值 3：智能化&quot;">​</a></h3><p>当系统线上化的规模越来越大，大数据就能产生更多的智能化。从市场角度看，外卖平台就是很典型的例子。随着线上的餐饮店越来越多，加入的用户越来越多，下单次数增加，系统就会根据你的下单习惯给你推荐更喜欢的商家，实现千人千面。这对用户来说，就是感觉系统更懂我，而商家也因为更精准的匹配提升了销量。</p><p>当规模逐渐增大，智能化的效应随之提升。比如像搜索广告这样的业务，从用户输入一个Query 到广告，最终的点击率是非常重要的指标，优化 0.1% 可能就会带来巨大的收入变化。这时候，市场对技术人的影响逐渐显现。</p><p>过去很长一段时间内，大数据研发、算法工程师都非常有市场，甚至算法工程师的薪水还比一般的技术岗高一点。但硬币都有另一面，这几年一些业务发展不如预期的企业，在裁员的时候，也会优先裁掉算法岗。这就是因为规模没有起来，很难发挥算法的优势。</p><h3 id="价值-4-底层能力建设" tabindex="-1">价值 4：底层能力建设 <a class="header-anchor" href="#价值-4-底层能力建设" aria-label="Permalink to &quot;价值 4：底层能力建设&quot;">​</a></h3><p>如果说前 3 类价值从市场显性应用层面都可以看到，那第 4 个价值就是隐性的底层能力建设价值，相当于助力技术更好、更快发展的“技术”。</p><p>这些年，做基础架构研发、底层系统研发的同学，从应用的各种组件、语言框架等，到研发流程中的效能工具，再到底层的数据库、云服务等方面，给上层应用的同学提供了很多好的平台和工具，助力技术服务业务。你也能看到过去很多大厂都在建设自己的云服务，其实都是为了抢占底层能力。</p><p>数字化、规模化、智能化、以及技术底层能力的建设，这是在变化的市场中，技术一直在发挥的价值。往小了说，你也能理解自己所在岗位的价值了。</p><h2 id="从当下市场需求看未来的方向" tabindex="-1">从当下市场需求看未来的方向 <a class="header-anchor" href="#从当下市场需求看未来的方向" aria-label="Permalink to &quot;从当下市场需求看未来的方向&quot;">​</a></h2><p>回到当下，我们可以明显地看到，在需求侧，移动互联网的渗透率已经达到天花板，加上复杂的国内外环境，市场增速明显放缓。同时，随着过去技术的发展，基础的平台、技术基建也已经有了很大的发展，互联网行业从原来的飞速发展期进入到了一个相对平稳的调整期。</p><p>供给侧，技术人才已经相当丰富，尤其在互联网大厂，其实已经非常明显地供大于求，何况还有即将加入的大学生年轻主力军。我们看到的大厂开始限制年龄，招聘上挑挑拣拣，其实都是供需关系发生变化的必然结果。</p><p>那前面提到的技术发挥价值的地方，在当下变化的市场背景下还有哪些空间呢？</p><p>我们看到，一方面，国家在推行供给侧改革，各个行业都在做数字化转型，另一方面，AI 技术在飞速发展，市场有句话叫“任何行业遇上 AI 都可以再做一遍”，未来还有很多可能性。</p><p>从“技术岗的 4 个价值”这个角度来看，除了规模化可能在大厂、大平台依然有需求，但增速不大以外，数字化、智能化、底层能力建设这 3 个价值依然有不错的发挥空间。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A8%8B%E5%BA%8F%E5%91%98%E8%81%8C%E4%B8%9A%E8%A7%84%E5%88%92%E6%89%8B%E5%86%8C/images/06-%25E8%25AE%25A4%25E8%25AF%2586%25E5%25B8%2582%25E5%259C%25BA/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A8%8B%E5%BA%8F%E5%91%98%E8%81%8C%E4%B8%9A%E8%A7%84%E5%88%92%E6%89%8B%E5%86%8C/images/06-%25E8%25AE%25A4%25E8%25AF%2586%25E5%25B8%2582%25E5%259C%25BA/2.png" alt=""></a></p><h3 id="数字化-传统行业的数字化转型" tabindex="-1">数字化：传统行业的数字化转型 <a class="header-anchor" href="#数字化-传统行业的数字化转型" aria-label="Permalink to &quot;数字化：传统行业的数字化转型&quot;">​</a></h3><p>互联网积累的数字化能力在传统行业数字化转型的过程中会非常有市场。当然，传统行业的场景会更复杂一些，除了数字化，可能还需要结合一些智能硬件，实现互联互通。</p><p>这是一片巨大的蓝海，很多行业的数字化程度非常低，急迫希望通过数字化实现一定的降本增效。比如内部作业的数字化， 就能方便精细化管理，还能打通上下游的数据等等。</p><p>举个例子，一个大型仓库数字化之后，一方面可以把内部的操作流程拣货、库存跟踪等全面线上化，另一方面可以跟上游的订单，比如电商系统的订单打通。当一个订单下来，能自动检测商品的信息，库存情况等等。这些可以大幅提升仓库作业效率，甚至还可以做一定的智能化，比如帮助仓库做订单预测，更好地优化库存管理。</p><p>对于个人来说，参与数字化转型有 2 种方式。一种是直接跳槽到传统行业，我在第 1 节分享过这样的故事，你可以翻回去看看 。第二种是加入一些为传统行业赋能的企业，比如现在很多大公司都有 ToB 的业务，利用自己的原有资源和技术能力，帮助传统行业做数字化转型。</p><p>当下很多技术人对于产业数字化不感冒，因为所做的工作跟原来互联网红利期时做的技术工作差异很大。</p><p>首先，场景更复杂，原来可能坐在工位跟产品对接需求就可以了，而做产业数字化，很多时候可能得深入客户现场，才能真正理解客户的需求。其次，合作的角色更多。比如一个小伙伴从互联网转型去生物医疗公司，发现公司光研发就有好多不同的方向，有做硬件的，有做嵌入式软件的，有做光学的，有做试剂的等等，每天要跟很多角色合作，才能把一个事情搞定。</p><p>虽然有这样、那样的不适应，又或者你觉得这样的技术工作不酷炫，但时代在变化，原有的岗位供大于求。这个时候，如果选择一个发展还不错的企业，用互联网积累的数字化、互联化技术帮助企业完成数字化转型，不是比天天卷 PPT、卷汇报有意义多了吗？另外，别忘了，技术的本质是工具。能用技术帮助真实世界解决疑难杂症，提升效率，技术的价值就得到了很大的发挥，你的岗位价值也是毋庸置疑的。</p><p>当然，在数字化转型中，你也不一定只是做传统的技术。其实未来还会诞生很多综合的岗位，比如我身边就有不少技术同学转型去做 ToB 业务的售前或者解决方案。这是一个综合性要求很高的岗位，不但需要懂销售、懂产品，更因为它是科技产品，所以还需要有很好的技术感觉，这其实也可以是技术人的一种发展选择。</p><h3 id="智能化-ai-未来可期" tabindex="-1">智能化：AI 未来可期 <a class="header-anchor" href="#智能化-ai-未来可期" aria-label="Permalink to &quot;智能化：AI 未来可期&quot;">​</a></h3><p>AI 当下非常火，很多人都蠢蠢欲动，我相信未来随着 AI 能力的发展，当 AI 真正像城市的水电煤一样成为基础设施时，很多行业都会发生很大的变化。不过目前看来还需要一些时间。</p><p>如果你原来的工作跟大模型完全不相关，只是听说很火，就想去试试，盲目投入，那么从职业发展的角度来看，我个人建议是不要冲动。AI 是很火，但是不是你的机会？不一定。古典老师有句话说，“在快速变化的时代， 最重要的不是什么是‘机会’， 而是什么是‘你的机会’”。你可能更需要思考，在如此拥挤的赛道里，你能不能挤得进去？</p><p>如果你原来就在做大模型，企业也有很好的投入，那 AI 可能是你的机会。AI 目前也需要不少时间来验证，这也是在考验你能不能熬得住。</p><p>其次，做好现有的积累，那么未来“用好 AI ”这件事上也有你的机会。AI 除了大模型，还有很大一块是与行业、场景结合的应用，这其中非常考验对于行业的认知，需要长时间的浸泡。从这个角度来说，深度参与过产业数字化转型的小伙伴，因为已经提前入行，懂得了行业的一些信息，也懂得了行业的一些高效路径，那么未来也有机会把 AI 应用做得更好。</p><p>这里澄清一个概念，智能化也不只 AI。刚举的外卖等等其他例子也是智能化的一部分。现存的互联网企业也存在机会，只是当下增速会放缓，人才供给也比较充足，如果你想入局，还需要考虑到这种情况，再做出选择。</p><h3 id="底层能力建设-赋能企业-攻坚-卡脖子-技术" tabindex="-1">底层能力建设：赋能企业，攻坚“卡脖子”技术 <a class="header-anchor" href="#底层能力建设-赋能企业-攻坚-卡脖子-技术" aria-label="Permalink to &quot;底层能力建设：赋能企业，攻坚“卡脖子”技术&quot;">​</a></h3><p>底层能力建设就好说了，分为两部分，一部分是随着产业数字化的深入，以及一些基础能力的国产化，对于底层的云服务、数据库、大数据能力建设都有很多需求。比如你看到的国内阿里云、百度云等云服务提供商。这其中很多底层引擎能力非常考验技术的专业性和深度，相关领域的同学依然会有不错的岗位需求。</p><p>另一部分，就是更底层的硬件能力。随着大国崛起，有很多“卡脖子”技术，比如芯片、精密元器件等，需要去做技术攻坚。相比之前互联网的应用技术，这些底层能力的建设周期会比较长，变化过程也会是逐步的，但未来会有更大的市场需求。不过对于做互联网软件开发的同学来说，转型跨度会比较大，更年轻的在校大学生可能相对合适。</p><h2 id="永恒的变化" tabindex="-1">永恒的变化 <a class="header-anchor" href="#永恒的变化" aria-label="Permalink to &quot;永恒的变化&quot;">​</a></h2><p>在这个“唯一不变的就是变化”的时代，技术岗未来大概率还会有很多变化，技术人希望“一招鲜”干到老，几乎是不可能的。提升面对变化和不确定性的能力，是我们永恒的命题。</p><p>那从个人职业发展角度，我们应该如何面对变化呢？一句话，“做一个终生学习者”。这句话你一定不陌生，那作为技术人，“终生学习”到底要学些什么东西呢？我认为有两部分。</p><p>第一部分，持续精进专业技术能力。一方面逐渐构建自己的技术体系，比如你可以不断丰富自己的技能树。另一方面，对于新技术，你还要有一定的解构能力。</p><p>什么意思呢？我们一部分的焦虑来自于不停出现的技术热点，但实际上，我们不需要每个新技术都去追，只要搞清楚技术原理，尤其是作者的初衷，理解它适用什么场景，解决什么问题，再根据自己的需要来取舍即可。</p><p>第二个部分，是向行业学习。前面提到过，技术说到底是一种工具，工具的价值体现在如何更好地解决真实世界的问题。而技术本身是专业性非常高的一个工种，有一定门槛。我们指望产品、业务同学透彻理解技术，还能知道什么场景下用什么技术解决问题，会很不现实。那么如果技术人希望发挥更大价值，就必须向前一步，向行业去学习。</p><p>那怎么向行业学习，又应该学习一些什么东西呢？下边的一些问题可能会对你有帮助。</p><ol><li><p>这个行业的商业模式是什么，也就是靠什么赚钱的？</p></li><li><p>行业的规模如何？头部玩家有哪些？它们的模式有哪些特色？</p></li><li><p>这个行业的上下游是谁？有哪些经典的作业场景？业务操作流程是什么样的？</p></li></ol><p>知道这些信息，就可以算是初步了解行业了。获取这些信息的方式一般有这三种。</p><ol><li><p>行业相关的书籍或者权威的行业研究报告，这些可以帮你了解行业的大致轮廓。</p></li><li><p>行业头部企业的官媒，比如公众号等，了解头部玩家的最新动态。</p></li><li><p>现场实地考察。</p></li></ol><p>举个例子，如果你想去了解物流行业，可以分为 3 步。</p><p>第一步，学习相关书籍和物流行业研究报告，做了这些，你会知道这个行业的发展历程、商业模式、行业规模等，非常典型的头部玩家有顺丰、京东等。</p><p>第二步，关注顺丰、京东企业的官媒。这些官方媒体上经常会发布企业的最新动态。比如引入了什么自动化设备，效能提高了多少，又和哪个公司合作了等等。这个虽然比较碎，但很具体，会帮你了解头部玩家当前重点关注的事情以及一些具体的场景。</p><p>当然了，如果你想真正进入到物流行业，那必须做到我们说的第三步，也是最重要的一步，实地考察。你可能要去实地仓库考察，看看外部订单进来之后，仓库如何拣货作业，作业流程是什么样的，库存如何管理等。</p><p>向行业学习更重要的一点是，保持敬畏心，理解“存在即合理”，去思考业务本身的客观规律是什么，现在的人到底用什么方法，为什么这么长时间他们积累的是这个方法来解决问题？只有找到背后的合理性，才能找到技术可以发挥作用的点。</p><p>分享一个我自己的例子，八年前我刚做外卖商家端时，有个最基础的功能是给商户打印小票，那时候市场上五花八门的打印机特别多。那么问题来了，商家 App 到底适配多少种打印机才合适？按照我们之前做线上系统的经验，可以先做市场调研，按覆盖率取头部，保障覆盖率超过 90% 的主流机型就差不多了。结果上线之后发现每天有商家投诉，为什么小票打印不出来，而竞对可以？</p><p>后来我跟着商圈经理去了商家的店，才真正明白，在午高峰嘈杂的餐厅里，打印小票对于外卖来说是非常关键的环节。关键环节一定是要 100% 甚至 200% 的投入，90% 完全就是糊弄。从那以后，我们才把能做的打印机机型都兼容，甚至还会定期收集市场需求，看看还有哪些需要兼容。</p><p>当你深入了解一个行业之后，就从技术人的代码舒适区中走出来了。回到真实的世界，向行业学习，你就更能知道技术这个犀利的工具如何在行业、场景下发挥作用。</p><h2 id="小结时刻" tabindex="-1">小结时刻 <a class="header-anchor" href="#小结时刻" aria-label="Permalink to &quot;小结时刻&quot;">​</a></h2><p>这一节我们回到了市场的本质——供需关系中，探讨了未来技术岗可能的场景。技术的本质是一个工具，未来技术的价值不会局限在互联网行业，而是在更多不同的行业、场景下去开花结果。</p><p>市场永远在变化，在当下的时代，没有任何能力可以帮你安身立命，安稳一生。唯有不断学习，提升专业能力，向行业学习，方能适应不断变化的市场。</p><p>技术的发展从来没有离开过市场的需求。作为技术人，可能你对某项技术有着独特的情怀，觉得这把“技术之剑”所向披靡，无所不能。但我们也要记住，不要神化技术。在心怀“技术改变世界”梦想的同时，更需要脚踏实地，从市场的需求中去思考技术的价值。</p><p>技术人的务实，从来不是只在办公室里冥思苦想，在大脑中自嗨，而是要走出实验室，回到真实的世界，敢于把自己的手弄脏，用技术这个犀利的工具解决真实世界里的一个又一个难题。</p><h2 id="聊聊发展" tabindex="-1">聊聊发展 <a class="header-anchor" href="#聊聊发展" aria-label="Permalink to &quot;聊聊发展&quot;">​</a></h2><p>最后咱们轻松点，聊聊你是怎么看待当下的市场环境的？对于未来，你有什么样的计划？欢迎留言分享。</p><p>如果觉得有所收获，也可以把课程分享给更多的朋友，一起学习程序员职业规划手册，心里不慌，脚下不乱，做好每一天的成长。</p>',81)])])}const u=a(t,[["render",r]]);export{E as __pageData,u as default};
